/* ===================== BÀI 26 · Tính giá trị nạp và sai số ===================== */
/* Bài 26 · Tính giá trị nạp và sai số (AMTS-EMB-001-M07-L02, MC51-026) — sinh bởi tools/author/mcu8051/l26.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR26=[{"label":"Ví dụ: Trễ 1 ms ở 12 MHz, nạp FC18H","code":"; Ví dụ 1: trễ 1 ms bằng Timer 0 chế độ 1 ở 12 MHz\n; N = 1 ms x 12 MHz / 12 = 1000 nhịp; nạp 65536 - 1000 = FC18H\n        ORG     0000H\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1\n        MOV     TH0,#0FCH               ; byte cao của FC18H\n        MOV     TL0,#18H                ; byte thấp\n        SETB    TR0\nCHO:    JNB     TF0,CHO                 ; 1000 nhịp = 1000 µs\n        CLR     TR0\n        CLR     TF0\n        CPL     P1.0                    ; đánh dấu mốc 1 ms trên LED P1.0\n        SJMP    $\n        END\n","note":"7 chu kỳ đầu đặt timer (MOV 2 + 2 + 2, SETB 1). Timer đếm 1000 nhịp từ chu kỳ 8 tới chu kỳ 1007 thì tràn; vòng JNB thấy cờ ngay trong chu kỳ đó. CLR TR0 vẫn được đếm (TL0 = 01H), rồi CLR TF0, CPL P1.0: dừng ở chu kỳ 1010 = 1000 nhịp đo + 10 chu kỳ của các lệnh quanh nó.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: 1 ms ở 11,0592 MHz và sai số làm tròn","code":"; Ví dụ 2: trễ 1 ms ở 11,0592 MHz: N = 921,6 không nguyên\n; Làm tròn N = 922: nạp 65536 - 922 = FC66H, sai số +0,4 nhịp\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TH0,#0FCH\n        MOV     TL0,#66H                ; 922 nhịp x 1,0851 µs = 1000,43 µs\n        SETB    TR0\nCHO:    JNB     TF0,CHO\n        CLR     TR0\n        CLR     TF0\n        CPL     P1.0\n        SJMP    $\n        END\n","note":"Cùng chương trình, thạch anh 11,0592 MHz, nạp FC66H (922 nhịp). Tổng 932 chu kỳ = 932 × 12 / 11,0592 ≈ 1011,285 µs; riêng phần timer đếm 922 nhịp ≈ 1000,43 µs, lệch +0,43 µs so với 1 ms do làm tròn 921,6 lên 922.","dev":{"led":true},"fosc":11059200},{"label":"Bẫy: Nạp N thay vì 65536 − N","code":"; Ví dụ 3 (bẫy): nạp thẳng N = 1000 = 03E8H thay vì 65536 - N\n; Timer đếm từ 03E8H lên FFFFH: 64 536 nhịp, gần 65 ms\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TH0,#03H                ; SAI: đây là N, không phải -N\n        MOV     TL0,#0E8H\n        SETB    TR0\nCHO:    JNB     TF0,CHO\n        CLR     TR0\n        CLR     TF0\n        CPL     P1.0\n        SJMP    $\n        END\n","note":"Nạp N = 03E8H thay vì −N: timer đếm từ 03E8H tới FFFFH rồi tràn, 65536 − 1000 = 64 536 nhịp. Chương trình dừng ở chu kỳ 64 546 (≈ 64,5 ms thay vì 1 ms). Ví dụ được chọn sẵn tốc độ chạy thời gian thực.","dev":{"led":true},"fosc":12000000,"speed":"real"},{"label":"Bẫy: Nạp lại bằng phần mềm thêm 10 chu kỳ","code":"; Ví dụ 4 (bẫy): nạp lại bằng phần mềm, chu kỳ dài hơn 100 nhịp\n; Mỗi vòng nạp FF9CH (100 nhịp) nhưng timer có lúc dừng\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     R7,#3                   ; 3 chu kỳ đảo P1.0\nLAI:    MOV     TH0,#0FFH               ; 65536 - 100 = FF9CH\n        MOV     TL0,#9CH\n        SETB    TR0\nCHO:    JNB     TF0,CHO\n        CLR     TR0                     ; timer dừng từ đây ...\n        CLR     TF0\n        CPL     P1.0                    ; mốc thời gian\n        DJNZ    R7,LAI                  ; ... tới SETB TR0 của vòng sau\n        SJMP    $\n        END\n","note":"Nạp 100 nhịp mỗi vòng nhưng P1.0 đổi ở chu kỳ 111, 221, 331: mỗi vòng 110 chu kỳ. 10 chu kỳ thừa là overhead: CLR TR0 (1, timer còn đếm nhưng vào số đã tràn), CLR TF0, CPL (2), DJNZ (2), hai MOV (4), SETB TR0 (1). Đo trên phần Thời gian.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Bù overhead, chu kỳ đúng 100 nhịp","code":"; Ví dụ 5: bù overhead: chu kỳ đảo P1.0 đúng 100 chu kỳ máy\n; Overhead mỗi vòng = 10 chu kỳ, nên nạp 65536 - 90 = FFA6H\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     R7,#3\nLAI:    MOV     TH0,#0FFH\n        MOV     TL0,#0A6H               ; 90 nhịp + 10 chu kỳ overhead\n        SETB    TR0\nCHO:    JNB     TF0,CHO\n        CLR     TR0\n        CLR     TF0\n        CPL     P1.0\n        DJNZ    R7,LAI\n        SJMP    $\n        END\n","note":"Nạp 90 nhịp (FFA6H) cho phần timer, cộng 10 chu kỳ overhead: P1.0 đổi đúng ở chu kỳ 101, 201, 301 — cách nhau 100. Thử thêm một NOP vào vòng lặp: chu kỳ lại thành 101, phải bù lại.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chế độ 2 tự nạp, không cần bù","code":"; Ví dụ 6: chế độ 2 tự nạp: chu kỳ 100 nhịp không cần bù\n; TH0 = 256 - 100 = 9CH; phần cứng nạp lại TL0 lúc tràn\n        ORG     0000H\n        MOV     TMOD,#02H               ; Timer 0 chế độ 2\n        MOV     TH0,#9CH\n        MOV     TL0,#9CH\n        MOV     R7,#3\n        SETB    TR0                     ; timer chạy liên tục\nCHO:    JNB     TF0,CHO\n        CLR     TF0\n        CPL     P1.0                    ; đảo đúng mỗi 100 chu kỳ máy\n        DJNZ    R7,CHO\n        CLR     TR0\n        SJMP    $\n        END\n","note":"Chế độ 2: TH0 = 9CH là giá trị nạp, timer chạy liên tục, phần cứng chép 9CH vào TL0 lúc tràn. P1.0 đổi ở chu kỳ 110, 210, 310: khoảng cách đúng 100 dù trong vòng có CLR TF0, CPL, DJNZ. Khi dừng TL0 = A1H (đã đếm thêm 5 nhịp sau lần tràn cuối).","dev":{"led":true},"fosc":12000000}];
const sim26=makeSim51(document.getElementById("m51-l26"),{id:"s26",presets:PR26,ram:256});
makeEx51(document.getElementById("ex-l26"),"l26",[{"t":"Giá trị nạp cho chế độ 1","d":"<p>Ô <code>30H<\/code> (byte cao), <code>31H<\/code> (byte thấp) chứa số nhịp N cần đếm (N = 0 nghĩa là 65 536 nhịp). Hãy: (1) đặt Timer 0 là bộ định thời chế độ 1 mà <b>giữ nguyên nửa TMOD của Timer 1<\/b>; (2) nạp TH0:TL0 = 65536 − N; (3) chép giá trị nạp vào <code>32H<\/code> (cao), <code>33H<\/code> (thấp). Chưa cho timer chạy (TR0 = 0). Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: N = 03E8H (1000) → TH0 = FCH, TL0 = 18H, 32H = FCH, 33H = 18H.<\/p>","start":"        ORG     0000H\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1\n        MOV     TH0,30H                 ; nạp N?\n        MOV     TL0,31H\n        MOV     32H,TH0\n        MOV     33H,TL0\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":232,"0x32":238,"0x33":238},"regs":{"TMOD":0}},"expect":{"iram":{"0x32":252,"0x33":24},"regs":{"TH0":252,"TL0":24,"TMOD":1},"bits":{"TR0":0}}},{"setup":{"iram":{"0x30":195,"0x31":80,"0x32":238,"0x33":238},"regs":{"TMOD":32,"PSW":128}},"expect":{"iram":{"0x32":60,"0x33":176},"regs":{"TH0":60,"TL0":176,"TMOD":33},"bits":{"TR0":0}}},{"setup":{"iram":{"0x30":0,"0x31":1,"0x32":238,"0x33":238},"regs":{"TMOD":0}},"expect":{"iram":{"0x32":255,"0x33":255},"regs":{"TH0":255,"TL0":255,"TMOD":1},"bits":{"TR0":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":238,"0x33":238},"regs":{"TMOD":16}},"expect":{"iram":{"0x32":0,"0x33":1},"regs":{"TH0":0,"TL0":1,"TMOD":17},"bits":{"TR0":0}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":238,"0x33":238},"regs":{"TMOD":33}},"expect":{"iram":{"0x32":255,"0x33":0},"regs":{"TH0":255,"TL0":0,"TMOD":33},"bits":{"TR0":0}}},{"setup":{"iram":{"0x30":3,"0x31":154,"0x32":238,"0x33":238},"regs":{"TMOD":32}},"expect":{"iram":{"0x32":252,"0x33":102},"regs":{"TH0":252,"TL0":102,"TMOD":33},"bits":{"TR0":0}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":238,"0x33":238},"regs":{"TMOD":0}},"expect":{"iram":{"0x32":0,"0x33":0},"regs":{"TH0":0,"TL0":0,"TMOD":1},"bits":{"TR0":0}}}]},"hints":["65536 − N trong 16 bit chính là số đối của N: lấy 0 trừ byte thấp, rồi 0 trừ byte cao có mượn.","CLR C rồi CLR A, SUBB A,31H cho byte thấp; CLR A (không đổi cờ CY), SUBB A,30H cho byte cao.","Nhớ bài 25: TMOD không định địa chỉ bit; giữ nửa Timer 1 bằng ANL rồi ORL."],"why":"Timer đếm lên tới FFFFH rồi tràn, nên muốn tràn sau N nhịp phải bắt đầu từ 65536 − N = −N (bù hai 16 bit). Phép trừ hai byte cần mượn (test 5: N = 0100H). Test 2, 4, 5, 6 có Timer 1 đang được dùng: MOV TMOD,#01H làm hỏng."},{"t":"Chia khoảng dài thành nhiều lần tràn","d":"<p>Một mốc thời gian dài N chu kỳ máy (24 bit: <code>30H<\/code> cao, <code>31H<\/code>, <code>32H<\/code> thấp; 1 ≤ N ≤ FEFFFFH) được tạo bằng Timer 0 chế độ 1: lần đầu đếm phần lẻ R = N mod 65536 (nếu R ≠ 0), các lần sau đếm đủ 65 536. Hãy tính: <code>33H<\/code> = số lần tràn K (bằng N / 65536 làm tròn lên); <code>34H<\/code> (cao), <code>35H<\/code> (thấp) = giá trị nạp cho lần đầu = 65536 − R (R = 0 thì nạp 0000H). Ô 30H–32H giữ nguyên.<\/p><p>Ví dụ: N = 1 000 000 = 0F4240H → K = 16 (10H), nạp BDC0H (lần đầu 4240H = 16 960 nhịp, rồi 15 lần × 65 536).<\/p>","start":"        ORG     0000H\n        MOV     A,30H\n        INC     A                       ; luôn thêm 1 lần tràn?\n        MOV     33H,A\n        MOV     34H,31H                 ; giá trị nạp?\n        MOV     35H,32H\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":15,"0x31":66,"0x32":64,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":15,"0x33":16,"0x34":189,"0x35":192}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":0,"0x33":238,"0x34":238,"0x35":238},"regs":{"PSW":128}},"expect":{"iram":{"0x30":1,"0x33":1,"0x34":0,"0x35":0}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":1,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":1,"0x33":2,"0x34":255,"0x35":255}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":1,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":0,"0x33":1,"0x34":255,"0x35":255}}},{"setup":{"iram":{"0x30":2,"0x31":0,"0x32":0,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":2,"0x33":2,"0x34":0,"0x35":0}}},{"setup":{"iram":{"0x30":1,"0x31":134,"0x32":160,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":1,"0x33":2,"0x34":121,"0x35":96}}},{"setup":{"iram":{"0x30":0,"0x31":195,"0x32":80,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":0,"0x33":1,"0x34":60,"0x35":176}}},{"setup":{"iram":{"0x30":254,"0x31":255,"0x32":255,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":254,"0x33":255,"0x34":0,"0x35":1}}}]},"hints":["N = (byte 30H) × 65536 + R, với R là hai byte 31H:32H. Số lần tràn đủ là giá trị ô 30H.","Nếu R ≠ 0 thì cần thêm 1 lần tràn lẻ: kiểm tra R = 0 bằng MOV A,31H rồi ORL A,32H và JZ.","Giá trị nạp = −R (bù hai 16 bit) như bài 1; khi R = 0 phép trừ tự cho 0000H."],"why":"Mọi mốc dài hơn 65 536 nhịp phải ghép nhiều lần tràn. Cách “phần lẻ trước, các lần đủ sau” chỉ cần nạp một lần lúc đầu; sau đó mỗi lần tràn TH0:TL0 đã về 0000H, đúng giá trị cho 65 536 nhịp tiếp theo. Test 2, 5 bắt lỗi luôn cộng thêm 1 lần."},{"t":"Dừng đúng T chu kỳ máy","d":"<p>Bộ chấm cho <b>Timer 1 chạy sẵn từ reset<\/b> (TMOD = 10H, TR1 = 1, TH1:TL1 = 0000H) để làm đồng hồ: khi chương trình dừng ở <code>SJMP $<\/code>, TH1:TL1 bằng tổng số chu kỳ máy đã chạy (tính cả một lần <code>SJMP $<\/code>). Ô <code>30H<\/code> (cao), <code>31H<\/code> (thấp) chứa T (số chẵn, 200 ≤ T ≤ 60000). Dùng <b>Timer 0 chế độ 1<\/b> (không đụng tới Timer 1) để chương trình dừng <b>đúng<\/b> sau T chu kỳ máy: TH1:TL1 = T. Mã dài không quá <b>24 byte<\/b>. Trang kiểm cả việc Timer 0 thật sự tràn (TF0 chuyển 0 → 1 trong lúc chạy): vòng trễ bằng lệnh, dù đúng T, vẫn chưa đạt.<\/p><p>Ví dụ: T = 03E8H (1000) → khi dừng TH1 = 03H, TL1 = E8H (1000 µs ở 12 MHz).<\/p>","start":"        ORG     0000H\n        MOV     TMOD,#01H               ; Timer 0 chế độ 1\n        CLR     C\n        CLR     A\n        SUBB    A,31H                   ; nạp 65536 - T (chưa bù)\n        MOV     TL0,A\n        CLR     A\n        SUBB    A,30H\n        MOV     TH0,A\n        SETB    TR0\nCHO:    JNB     TF0,CHO\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":232},"regs":{"TMOD":16,"TCON":64}},"expect":{"regs":{"TH1":3,"TL1":232,"TMOD":17},"bits":{"TR1":1},"rise":{"TF0":1}}},{"setup":{"iram":{"0x30":0,"0x31":200},"regs":{"TMOD":16,"TCON":64,"PSW":128}},"expect":{"regs":{"TH1":0,"TL1":200,"TMOD":17},"bits":{"TR1":1},"rise":{"TF0":1}}},{"setup":{"iram":{"0x30":19,"0x31":136},"regs":{"TMOD":16,"TCON":64}},"expect":{"regs":{"TH1":19,"TL1":136,"TMOD":17},"bits":{"TR1":1},"rise":{"TF0":1}}},{"setup":{"iram":{"0x30":78,"0x31":32},"regs":{"TMOD":16,"TCON":64}},"expect":{"regs":{"TH1":78,"TL1":32,"TMOD":17},"bits":{"TR1":1},"rise":{"TF0":1}}},{"setup":{"iram":{"0x30":234,"0x31":96},"regs":{"TMOD":16,"TCON":64}},"expect":{"regs":{"TH1":234,"TL1":96,"TMOD":17},"bits":{"TR1":1},"rise":{"TF0":1}}},{"setup":{"iram":{"0x30":4,"0x31":210},"regs":{"TMOD":16,"TCON":64}},"expect":{"regs":{"TH1":4,"TL1":210,"TMOD":17},"bits":{"TR1":1},"rise":{"TF0":1}}},{"setup":{"iram":{"0x30":30,"0x31":98},"regs":{"TMOD":16,"TCON":64}},"expect":{"regs":{"TH1":30,"TL1":98,"TMOD":17},"bits":{"TR1":1},"rise":{"TF0":1}}},{"setup":{"iram":{"0x30":117,"0x31":50},"regs":{"TMOD":16,"TCON":64}},"expect":{"regs":{"TH1":117,"TL1":50,"TMOD":17},"bits":{"TR1":1},"rise":{"TF0":1}}}],"maxCyc":60000,"maxBytes":24},"hints":["Chạy code mẫu với T = 1000 rồi xem tổng chu kỳ: chênh với 1000 bao nhiêu? Đó là overhead cố định của chương trình (các lệnh trước SETB TR0 và SJMP $), cộng với độ trễ của vòng hỏi.","Nạp −(T − C) thay vì −T, với C là overhead: phép trừ hai byte vẫn như bài 1, chỉ đổi số bị trừ của byte thấp từ 0 thành C.","Vòng JNB TF0,$ tốn 2 chu kỳ: nếu C làm số nhịp đếm (T − C) lẻ, chương trình thoát trễ thêm 1 chu kỳ. T luôn chẵn nên chọn C chẵn để độ trễ này cố định bằng 0."],"why":"Thời gian thật = số nhịp timer + overhead của các lệnh trước khi timer chạy và sau khi thoát vòng hỏi + độ trễ phát hiện cờ (0 hoặc 1 chu kỳ). Lời giải tham chiếu: ORL TMOD (giữ Timer 1), tính −(T − 12), SETB TR0 ở chu kỳ 10, thoát vòng hỏi đúng lúc tràn (T − 2), SJMP $ thêm 2: tổng T, 22 byte. Code mẫu dùng MOV TMOD,#01H làm Timer 1 thành chế độ 0 nên đồng hồ đo sai, và không bù overhead."}]);

makeQuiz("quiz26","score26",[{"q": "Thạch anh 12 MHz, Timer 0 chế độ 1, cần cờ tràn sau 20 ms. Nạp TH0:TL0 bằng bao nhiêu?", "o": ["4E20H (20000)", "B1E0H (65536 − 20000)", "FFECH (65536 − 20)", "Không được: 20 ms vượt một lần tràn"], "a": 1, "e": "N = 20 ms × 1 MHz = 20 000 nhịp; 65536 − 20000 = 45 536 = B1E0H. 4E20H là N nạp thẳng (lỗi ví dụ 3). 20 ms < 65,536 ms nên một lần tràn là đủ."}, {"q": "Thạch anh 11,0592 MHz, cần 1 ms. Nạp FC66H (922 nhịp). Sai số so với 1 ms xấp xỉ bao nhiêu?", "o": ["0 µs, vì 922 là số nguyên", "−78 µs", "+1,085 µs (đúng một nhịp)", "+0,43 µs (khoảng 0,043 %)"], "a": 3, "e": "N lý tưởng = 921,6; làm tròn 922 thừa 0,4 nhịp × 1,0851 µs ≈ 0,43 µs; 0,4 / 921,6 ≈ 0,043 %. Làm tròn tới số gần nhất thì sai không quá nửa nhịp."}, {"q": "Vòng nạp lại phần mềm có overhead 10 chu kỳ (từ lúc tràn tới lúc timer chạy lại). Muốn chu kỳ đúng 500 nhịp ở chế độ 1, nạp bao nhiêu?", "o": ["65536 − 490 = FE16H", "65536 − 500 = FE0CH", "65536 − 510 = FE02H", "256 − 500"], "a": 0, "e": "Chu kỳ = số nhịp timer + overhead, nên số nhịp = 500 − 10 = 490; 65536 − 490 = 65 046 = FE16H. Nạp FE0CH cho chu kỳ 510 (ví dụ 4)."}, {"q": "Vì sao chế độ 2 tạo chuỗi tràn đều hơn chế độ 1 nạp lại bằng phần mềm?", "o": ["Phần cứng chép TH vào TL ngay lúc tràn, timer không dừng nên phần mềm không làm lệch chu kỳ", "Chế độ 2 đếm nhanh gấp đôi", "Chế độ 2 tự xóa cờ TF0", "Chế độ 2 dùng thạch anh riêng"], "a": 0, "e": "Ở chế độ 2 việc nạp lại không cần lệnh nào, nên các lệnh phần mềm không chen vào giữa hai lần đếm (ví dụ 6). Cờ TF0 vẫn phải xóa bằng phần mềm khi hỏi vòng."}, {"q": "Cần mốc 1 s ở 12 MHz bằng Timer 0 chế độ 1, cách “phần lẻ trước”. Lần đầu nạp gì và tổng cộng bao nhiêu lần tràn?", "o": ["Nạp 4240H, 15 lần tràn", "Nạp 0000H, 15 lần tràn", "Nạp BDC0H, 16 lần tràn", "Nạp BDC0H, 15 lần tràn"], "a": 2, "e": "1 000 000 = 0F4240H: phần lẻ R = 4240H, nạp −R = BDC0H cho lần đầu, rồi 15 lần đủ 65 536 (TH:TL đã về 0000H): 1 + 15 = 16 lần."}]);

fillSnips();
